  END LOOP;
  FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='noor_r386_candidate' LOOP
   IF has_function_privilege(role_name,f.oid,'EXECUTE') THEN RAISE EXCEPTION 'R386_FUNCTION_LEAK'; END IF;
  END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='noor_r386_candidate' AND r.relkind='r' AND r.relrowsecurity AND r.relforcerowsecurity)<>5 THEN RAISE EXCEPTION 'R386_RLS_MISSING'; END IF;
